// LIBRARY.JS — 30 prompts × 3 languages (complete)
// Each prompt: { num, cat, numBg, numColor, badgeBg, badgeColor, title:{fr,en,ar}, badge:{fr,en,ar}, desc:{fr,en,ar}, code:{fr,en,ar}, source }
